def separate_paren_groups(paren_string: str) -> List[str]:
    """Separate groups of nested parentheses from a string."""
    stack = []
    groups = []
    group = ''

    for char in paren_string:
        if char in '()':
            if char == '(':
                stack.append(char)
                group += char
            elif char == ')' and stack:
                stack.pop()
                group += char
